import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Card background plane
  const cardGeometry = new THREE.PlaneGeometry(1, 1);
  const cardTexture = ctx.textureLoader.load(config.assets.imageUrl);

  const cardMaterial = new THREE.MeshBasicNodeMaterial({
    map: cardTexture,
    transparent: true,
  });

  const cardMesh = new THREE.Mesh(cardGeometry, cardMaterial);
  group.add(cardMesh);

  // Text overlay
  if (config.textContent && config.textContent.length > 0) {
    const textMesh = ctx.fontAtlas.createText(config.textContent[0], {
      size: 0.34,
      weight: 400,
      color: 0x16161d,
    });
    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    cardGeometry.dispose();
    cardMaterial.dispose();
    if (cardTexture) cardTexture.dispose();
  };

  // Event handlers (none for this static element)
  group.userData.handlers = {};

  return group;
}
